"""Original V1.0 backup generated by original modules, then restored by Reviewed."""
import hashlib
import json
import os
from pathlib import Path
import sqlite3
import subprocess
import sys
import tempfile
import unittest
import zipfile

from database.store import Store, SCHEMA_VERSION
from services.export_backup import ExportBackupService
from services.materials import MaterialService, sha256_file
from services.portfolio import PortfolioService


def create_original_backup(base):
    """Read original immutable modules in a separate process; fixture data is temporary."""
    original = Path(__file__).resolve().parents[2] / 'ResearchPortfolioManager'
    if not (original / 'main.py').is_file():
        raise unittest.SkipTest('原 V1.0 源码目录未提供，原版生成备份兼容测试未运行')
    base = Path(base)
    script = r'''
import json
from pathlib import Path
import sqlite3
import sys
sys.dont_write_bytecode = True
original = Path(sys.argv[1]).resolve()
base = Path(sys.argv[2]).resolve()
sys.path.insert(0, str(original))
from database.store import Store
from services.portfolio import PortfolioService
from services.materials import MaterialService
from services.export_backup import ExportBackupService
assert Path(sys.modules['database.store'].__file__).resolve().is_relative_to(original)
store = Store(base / '原版临时资料')
store.save_config({'name':'旧版测试姓名','demo':True})
portfolio = PortfolioService(store)
pid = portfolio.save_project({'name':'【演示】原版生成备份', 'leader':'旧版测试姓名', 'description':'<旧版 & 兼容>'})
tid = portfolio.save_task({'project_id':pid, 'title':'旧版关联任务', 'due_date':'2026-10-10'})
aid = portfolio.save_achievement({'project_id':pid, 'name':'旧版关联成果', 'type':'其他成果','status':'准备中'})
source = base / '旧版 来源.txt'
source.write_text('原版备份兼容材料\n', encoding='utf-8')
mid = MaterialService(store).import_file(source, pid, aid, version_label='旧版 V1')
portfolio.archive_project(pid)
backup = ExportBackupService(store).backup(base / 'actual-original-V1.0.zip')
with store.connection() as connection:
    schema = [list(row) for row in connection.execute("SELECT type,name,tbl_name,sql FROM sqlite_master ORDER BY type,name")]
    records = {table:[dict(row) for row in connection.execute('SELECT * FROM '+table+' ORDER BY id')]
               for table in ('projects','tasks','achievements','materials')}
meta = {'module':str(Path(sys.modules['database.store'].__file__).resolve()),
        'schema':schema,'records':records,'schema_version':store.schema_version,
        'config':store.config,'backup':str(backup),'material_id':mid}
(base / 'original-fixture-evidence.json').write_text(json.dumps(meta, ensure_ascii=False, indent=2), encoding='utf-8')
print('Original backup generated with original V1.0 modules in isolated temporary data.')
'''
    env = dict(os.environ, PYTHONDONTWRITEBYTECODE='1', PYTHONIOENCODING='utf-8')
    result = subprocess.run([sys.executable, '-B', '-c', script, str(original), str(base)],
                            cwd=base, env=env, text=True, encoding='utf-8',
                            capture_output=True, timeout=30)
    if result.returncode:
        raise AssertionError(f'原版隔离备份生成失败：{result.stdout}\n{result.stderr}')
    meta = json.loads((base / 'original-fixture-evidence.json').read_text(encoding='utf-8'))
    return Path(meta['backup']), meta


def repackage_config(archive, destination, values):
    """Semantic configuration test: rehash modified settings so checksum still validates."""
    with zipfile.ZipFile(archive) as package:
        members = {name: package.read(name) for name in package.namelist()}
    content = json.dumps(values, ensure_ascii=False, indent=2).encode('utf-8')
    members['config/settings.json'] = content
    manifest = json.loads(members['manifest.json'])
    manifest['files']['config/settings.json'] = {'size': len(content), 'sha256': hashlib.sha256(content).hexdigest()}
    members['manifest.json'] = json.dumps(manifest, ensure_ascii=False).encode('utf-8')
    with zipfile.ZipFile(destination, 'w', zipfile.ZIP_DEFLATED) as package:
        for name, content in members.items():
            package.writestr(name, content)
    return destination


class ReviewedBackupCompatibilityTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.fixture_temp = tempfile.TemporaryDirectory(prefix='旧版兼容 fixture ')
        cls.backup, cls.meta = create_original_backup(Path(cls.fixture_temp.name))

    @classmethod
    def tearDownClass(cls):
        cls.fixture_temp.cleanup()

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix='恢复修订 中文 ')
        self.base = Path(self.temp.name)
        self.current = Store(self.base / '当前资料')
        self.service = ExportBackupService(self.current)
        PortfolioService(self.current).save_project({'name': '当前资料必须保留'})

    def tearDown(self):
        self.temp.cleanup()

    def current_records(self):
        with self.current.connection() as connection:
            return [dict(row) for row in connection.execute('SELECT * FROM projects')]

    def test_actual_original_v1_backup_restores_full_schema_records_links_hashes(self):
        before = self.current_records()
        target = self.base / '从原版恢复'
        target.mkdir()
        self.assertEqual(self.service.restore(self.backup, target), target)
        restored = Store(target)
        self.assertEqual(SCHEMA_VERSION, 1)
        self.assertEqual(restored.schema_version, self.meta['schema_version'])
        with restored.connection() as connection:
            schema = [list(row) for row in connection.execute(
                'SELECT type,name,tbl_name,sql FROM sqlite_master ORDER BY type,name')]
            self.assertEqual(schema, self.meta['schema'])
            for table in ('projects', 'tasks', 'achievements', 'materials'):
                records = [dict(row) for row in connection.execute('SELECT * FROM '+table+' ORDER BY id')]
                self.assertEqual(records, self.meta['records'][table])
            self.assertEqual(connection.execute('PRAGMA foreign_key_check').fetchall(), [])
            self.assertEqual(connection.execute('PRAGMA integrity_check').fetchone()[0], 'ok')
        material = MaterialService(restored)
        path = material.file_path(self.meta['material_id'], verify=True)
        self.assertEqual(sha256_file(path), self.meta['records']['materials'][0]['sha256'])
        self.assertEqual(restored.config, self.meta['config'])
        self.assertTrue(PortfolioService(restored).get_project(1)['archived'])
        self.assertEqual(self.current_records(), before)

    def test_backup_config_omitted_fields_merge_without_rewriting_restored_bytes(self):
        modified = repackage_config(self.backup, self.base / '缺省配置备份.zip', {'name': '仅含姓名的兼容配置'})
        target = self.base / '缺省配置恢复'
        self.service.restore(modified, target)
        restored = Store(target)
        self.assertEqual(restored.config['name'], '仅含姓名的兼容配置')
        self.assertIs(restored.config['demo'], False)
        self.assertIsInstance(restored.config['background'], str)
        self.assertIsInstance(restored.config['interests'], str)
        self.assertEqual(json.loads(restored.config_path.read_text(encoding='utf-8')),
                         {'name': '仅含姓名的兼容配置'})

    def test_rehashed_invalid_backup_config_rejected_by_field_target_current_unchanged(self):
        before_records = self.current_records()
        before_config = self.current.config_path.read_bytes()
        for index, (field, invalid) in enumerate([('name', None), ('name', ' '), ('background', 123),
                                                  ('interests', []), ('demo', 'false')]):
            with self.subTest(field=field, value=invalid):
                bad = repackage_config(self.backup, self.base / f'错误配置{index}.zip',
                                       dict(self.meta['config'], **{field: invalid}))
                target = self.base / f'空恢复目标{index}'
                target.mkdir()
                with self.assertRaisesRegex(ValueError, field):
                    self.service.restore(bad, target)
                self.assertEqual(list(target.iterdir()), [])
                self.assertEqual(self.current_records(), before_records)
                self.assertEqual(self.current.config_path.read_bytes(), before_config)

    def test_backup_rejects_invalid_live_settings_without_overwriting_file_or_existing_package(self):
        prior_package = self.base / '原备份.zip'
        prior_package.write_bytes(b'preexisting destination remains')
        config_bytes = json.dumps(dict(self.current.config, demo='false')).encode('utf-8')
        self.current.config_path.write_bytes(config_bytes)
        with self.assertRaisesRegex(ValueError, 'demo'):
            self.service.backup(prior_package)
        self.assertEqual(self.current.config_path.read_bytes(), config_bytes)
        self.assertEqual(prior_package.read_bytes(), b'preexisting destination remains')


if __name__ == '__main__':
    unittest.main(verbosity=2)
